import{t as e}from"./utils-COoNfFoj.js";var t={slug:`mariya-valeva`,influencerName:`Mariya Valeva`,influencerHandle:`@MariyaValeva`,influencerAvatarUrl:`${e}/mariya-valeva-avatar.jpg`,heroDescription:`Scaling founders are constantly trying to figure out what’s actually happening in the business, but the answers usually live across fragmented dashboards, spreadsheets, board decks, and Slack messages that start with “quick question on cash…”. After 13+ years in startup finance, I got tired of watching teams only connect the dots once the problem was already expensive, so I built Margin Signals to catch the slow burn issues founders usually don’t see until they’re rewriting forecasts, cutting costs, or explaining surprises to the board.`,assetTitle:`Nexus AI`,screenshotUrl:`${e}/mariya-valeva.png`,remixUrl:`https://www.perplexity.ai/computer/a/de053309-d3dd-4fba-8f02-85233837b18b`,promptTitle:`Try Mariya's prompt`,promptText:`Build a real-time dashboard for scaling startup founders that combines financial metrics, operational signals, founder briefings, market intelligence, and company benchmarking into one place. The goal is to help founders instantly understand what changed in the business, where risks are emerging, what’s drifting off track, and what needs attention before it becomes a bigger problem. Include live tracking for runway, burn multiple, ARR growth, hiring pace, collections vs burn, churn signals, forecast vs actual performance, weekly cash flow movement, operational bottlenecks, and progress toward annual company goals. Add proactive alerts, investor-style observations, competitor and funding activity, and benchmark comparisons across growth, efficiency, hiring, margins, runway health, and operational performance against similar-stage companies. The dashboard should also generate weekly founder summaries explaining what changed, what metrics are improving or worsening, and what decisions likely need to be made next. The experience should feel modern, premium, highly visual, and practical, something founders would realistically check every morning to run the company.`};export{t as default};
